actions.script:
const portal=ec.resource.script('component://mr-pass/screen/Shared/Portal.js'),p=ec.web.parameters
const token=p.token || null,orderId=token ? null : p.orderId || null
const base=publicPath.replace(/\/submit$/,'')
const query=(values)=>'?'+Object.entries(values).filter(([k,v])=>v).map(([k,v])=>k+'='+encodeURIComponent(v)).join('&')
const out=portal.attempt('submitSupplierBill',{siteId:resolvedSiteId,token,orderId,operationId:p.operationId,referenceNumber:p.referenceNumber,invoiceDate:p.invoiceDate || null,amount:p.amount || null,file:ec.web.multiPartParameters?.file})
if(out.error){ec.web.sessionAttributes.passBillError=out.error.message;ec.web.response.sendRedirect(base+query({token,orderId}));return}
ec.web.response.sendRedirect(base+query({token,orderId,submissionId:out.result.submission.submissionId}))

const portal=ec.resource.script('component://mr-pass/screen/Shared/Portal.js'),p=ec.web.parameters
token=p.token || null
billError=ec.web.sessionAttributes.passBillError || null
if(billError)ec.web.sessionAttributes.remove('passBillError')
view=null;failure=null
const orderId=token ? null : p.orderId || null
if(!token && !orderId)failure={kind:'NotFound',message:'Open the link the buyer sent with the purchase order.'}
else{
    const found=portal.attempt('getSubmission',{siteId:resolvedSiteId,token,orderId,submissionId:p.submissionId || null})
    if(found.error)failure=found.error
    else view=found.result
}
submitOperationId=portal.operationId()
